-- Retain legacy whole-standard selection semantics and stable task item IDs.
ALTER TABLE eam_maintenance_plan_device ADD legacy_standard_id BIGINT NULL COMMENT '历史整标准选择ID；明确项目选择时为空';
UPDATE eam_maintenance_plan_device d JOIN migration_v67_maintenance_schedule_archive a ON a.tenant_id=d.tenant_id AND a.id=d.id SET d.legacy_standard_id=NULLIF(CAST(JSON_UNQUOTE(JSON_EXTRACT(a.payload,'$.standardId')) AS UNSIGNED),0) WHERE JSON_CONTAINS_PATH(a.payload,'one','$.projectRefs')=0;
INSERT INTO eam_maintenance_device_project(tenant_id,device_id,standard_id,item_key,sort_no) SELECT d.tenant_id,d.id,i.standard_id,i.item_key,i.sort_no FROM eam_maintenance_plan_device d JOIN eam_maintenance_standard_item i ON i.tenant_id=d.tenant_id AND i.standard_id=d.legacy_standard_id AND i.type_id=d.type_id;
CREATE OR REPLACE VIEW v_maintenance_schedule AS SELECT d.*, COALESCE(d.legacy_standard_id,(SELECT r.standard_id FROM eam_maintenance_device_project r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id ORDER BY r.sort_no LIMIT 1),0) AS standard_id,JSON_REMOVE(JSON_OBJECT('id',CAST(d.id AS CHAR),'equipmentId',CAST(d.equipment_id AS CHAR),'typeId',CAST(d.type_id AS CHAR),'nextDate',DATE_FORMAT(d.next_date,'%Y-%m-%d'),'period',d.`period_count`,'unit',d.`period_unit`,'validDays',d.`valid_days`,'remark',d.`remark`,'owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_device_person r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_device_person r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'projectRefs',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('standardId',CAST(r.standard_id AS CHAR),'itemId',r.item_key)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_device_project r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id LIMIT 1),JSON_ARRAY()),'standardId',CAST(COALESCE(d.legacy_standard_id,(SELECT r.standard_id FROM eam_maintenance_device_project r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id ORDER BY r.sort_no LIMIT 1),0) AS CHAR)),IF(d.legacy_standard_id IS NULL,'$.unusedCompatibilityKey','$.projectRefs')) AS payload FROM eam_maintenance_plan_device d;
